def fetch_json(url: str):
    with request.urlopen(url, timeout=5) as response:
        return json.loads(response.read().decode())

def fetch_text(url: str, data: bytes | None = None):
    req = request.Request(url, data=data, headers={"content-type": "application/json"})
    with request.urlopen(req, timeout=90) as response:
        return response.read().decode()

def extract_keys(config_path: Path):
    rows = []
    for line in config_path.read_text().splitlines():
        if not line.startswith('|') or 'Config key path' in line or line.startswith('|---'):
            continue
        cells = [c.strip() for c in line.strip().split('|')[1:-1]]
        if len(cells) < 3:
            continue
        key_cell = cells[2]
        if key_cell == '—' or key_cell.startswith('see ') or key_cell.startswith('shared '):
            continue
        for raw in re.findall(r'`([^`]+)`', key_cell):
            for part in raw.split('<br>'):
                part = part.strip()
                if part:
                    rows.append(part)
    return rows

def main() -> int:
    parser = argparse.ArgumentParser(description='Check Task 11 manual smoke manifest coverage.')
    parser.add_argument('--matrix', default='docs/skippy/CONFIGURATION.md')
    parser.add_argument('--manifest', default='docs/skippy/manual-smoke/manifest.tsv')
    args = parser.parse_args()

    matrix_keys = extract_keys(Path(args.matrix))
    with Path(args.manifest).open(newline='') as fh:
        rows = list(csv.DictReader(fh, delimiter='	'))

    manifest_keys = [row['key_path'] for row in rows]
    missing = [key for key in matrix_keys if key not in manifest_keys]
    duplicates = sorted({key for key in manifest_keys if manifest_keys.count(key) > 1})
    extras = [key for key in manifest_keys if key not in matrix_keys]
    failures = []

    for row in rows:
        key = row['key_path']
        status = row['pass_fail_status'].strip()
        if status not in ALLOWED_STATUSES:
            failures.append(f'invalid status for {key}: {status or "<blank>"}')
        fixture_path = row['fixture_path'].strip()
        if not fixture_path or not Path(fixture_path).exists():
            failures.append(f'missing fixture for {key}: {row["fixture_path"]}')
        for field in ('fixture_path', 'startup_apply_command', 'model_identifier', 'verification_command', 'expected_result', 'actual_evidence_path'):
            value = row[field].strip()
            if not value:
                failures.append(f'blank {field} for {key}')
                continue
            if PLACEHOLDER_RE.search(value):
                failures.append(f'placeholder value in {field} for {key}: {value}')
            if field != 'actual_evidence_path' and has_forbidden_tracked_path(value):
                failures.append(f'machine-local path in {field} for {key}: {value}')
        evidence_path = row['actual_evidence_path'].strip()
        if evidence_path:
            p = Path(evidence_path)
            if not is_non_empty_file(p):
                failures.append(f'empty or missing evidence file for {key}: {evidence_path}')
        command = row['startup_apply_command'].strip()
        model = row['model_identifier'].strip()
        expected = row['expected_result'].strip()
        if status in {'PASS', 'EXPECTED_REJECTED_PASS'}:
            if 'not-run locally' in command.lower():
                failures.append(f'non-executable command marked successful for {key}')
        if status == 'PASS':
            if '--model-path $MESH_LLM_SMOKE_MODEL_PATH' not in command:
                failures.append(f'portable model env var missing for PASS row {key}')
        if key.startswith('speculative.') and status == 'PASS':
            if '--draft-path $MESH_LLM_SMOKE_DRAFT_PATH' not in command:
                failures.append(f'portable draft env var missing for speculative PASS row {key}')
        if status.startswith('BLOCKED_') and not expected:
            failures.append(f'blocked row missing blocker explanation for {key}')
        if PORTABLE_ENV_RE.search(model) and status != 'PASS':
            failures.append(f'env var leaked into non-PASS model identifier for {key}')

    evidence_files = {
        Path('.sisyphus/evidence/task-11-manual-runtime-smoke.txt'),
        Path('.sisyphus/evidence/task-11-manual-runtime-smoke-error.txt'),
    }
    for evidence in evidence_files:
        if not is_non_empty_file(evidence):
            failures.append(f'evidence file empty: {evidence}')
        else:
            content = evidence.read_text()
            if 'COMMAND:' not in content and 'Coverage check' not in content:
                failures.append(f'evidence file missing command/result markers: {evidence}')

    if missing or duplicates or extras or failures:
        if missing:
            print('Missing key paths:')
            for key in missing:
                print(key)
        if duplicates:
            print('Duplicate manifest keys:')
            for key in duplicates:
                print(key)
        if extras:
            print('Extra manifest keys:')
            for key in extras:
                print(key)
        if failures:
            print('Manifest/evidence failures:')
            for failure in failures:
                print(failure)
        return 1

    print(f'Coverage OK: {len(matrix_keys)} matrix keys, {len(rows)} manifest rows')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

def http_json(
    url: str,
    payload: dict[str, Any],
    api_key: str | None,
    timeout: float,
) -> dict[str, Any]:
    headers = {"content-type": "application/json"}
    if api_key:
        headers["authorization"] = f"Bearer {api_key}"
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers=headers,
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))

def llama_payload(prompt: str, max_tokens: int, cache_prompt: bool) -> dict[str, Any]:
    return {
        "prompt": prompt,
        "n_predict": max_tokens,
        "temperature": 0,
        "top_k": 1,
        "cache_prompt": cache_prompt,
    }

def skippy_payload(
    model: str,
    shared_prefix: str,
    tail: str,
    max_tokens: int,
) -> dict[str, Any]:
    return {
        "model": model,
        "messages": [
            {"role": "system", "content": shared_prefix},
            {"role": "user", "content": tail},
        ],
        "temperature": 0,
        "top_p": 1,
        "max_tokens": max_tokens,
    }

def prompt_text(request: BenchRequest, tail: str) -> str:
    return f"System prefix:
{request.shared_prefix}

User request:
{tail}
"

def cached_tokens_from_skippy(response: dict[str, Any]) -> int:
    usage = response.get("usage") or {}
    details = usage.get("prompt_tokens_details") or {}
    value = details.get("cached_tokens", 0)
    return int(value) if isinstance(value, (int, float)) else 0

def prompt_tokens_from_skippy(response: dict[str, Any]) -> int:
    usage = response.get("usage") or {}
    value = usage.get("prompt_tokens", 0)
    return int(value) if isinstance(value, (int, float)) else 0

def cache_tokens_from_llama(response: dict[str, Any]) -> int:
    timings = response.get("timings") or {}
    for key in ("cache_n", "tokens_cached"):
        value = timings.get(key)
        if isinstance(value, (int, float)):
            return int(value)
    return 0

def prompt_tokens_from_llama(response: dict[str, Any]) -> int:
    timings = response.get("timings") or {}
    for key in ("prompt_n", "tokens_evaluated"):
        value = timings.get(key)
        if isinstance(value, (int, float)):
            return int(value)
    return 0

def cacheable_prefix_tokens(prompt_tokens: int, backend: str) -> int:
    if backend == "skippy-openai":
        return max(prompt_tokens - 1, 0)
    return prompt_tokens

def cache_status(cache_mode: str, cached_tokens: int) -> str:
    if "disabled" in cache_mode or "false" in cache_mode:
        return "disabled"
    if cached_tokens > 0:
        return "hit"
    return "miss"

def hit_kind(backend: str, status: str) -> str:
    if status != "hit":
        return "none"
    if backend == "llama-server":
        return "llama_prompt_cache"
    return "usage_cached_tokens"

def run_observation(
    backend: str,
    cache_mode: str,
    elapsed_ms: float,
    prompt_tokens: int,
    cached_tokens: int,
    run: int | None = None,
) -> dict[str, Any]:
    observation = {
        "elapsed_ms": elapsed_ms,
        "prompt_tokens": prompt_tokens,
        **cache_observation(backend, cache_mode, prompt_tokens, cached_tokens),
    }
    if run is not None:
        observation = {"run": run, **observation}
    return observation

def cache_verdict(cache_mode: str, cached_tokens: list[int]) -> str:
    if "disabled" in cache_mode or "false" in cache_mode:
        return (
            "PASS disabled/no-cache"
            if all(cached == 0 for cached in cached_tokens)
            else "FAIL disabled cached"
        )
    if cached_tokens and all(cached > 0 for cached in cached_tokens):
        return "PASS all-hit"
    return "FAIL missed-hit"

def format_range(min_value: int | float, max_value: int | float, suffix: str = "") -> str:
    if min_value == max_value:
        return f"{min_value}{suffix}"
    return f"{min_value}{suffix}-{max_value}{suffix}"

def format_percent_range(min_value: float, max_value: float) -> str:
    if min_value == max_value:
        return f"{min_value:.1%}"
    return f"{min_value:.1%}-{max_value:.1%}"

def build_request(prefix_repetitions: int, pattern: str) -> BenchRequest:
    prefix = "Skippy prompt cache benchmark shared prefix. " * prefix_repetitions
    measured_tail = "Measure the reusable prefix and answer with the word measured."
    warmup_tail = measured_tail
    if pattern == "shared-prefix":
        warmup_tail = "Warm the reusable prefix and answer with the word warmup."
    return BenchRequest(
        shared_prefix=prefix,
        warmup_tail=warmup_tail,
        measured_tail=measured_tail,
        pattern=pattern,
    )

def require_warm_cache(rows: list[dict[str, Any]]) -> None:
    warm_rows = [row for row in rows if row["name"] in {"warm native", "warm Skippy"}]
    failures = [
        row["name"]
        for row in warm_rows
        if not isinstance(row.get("max_cached_tokens"), int)
        or row["max_cached_tokens"] <= 0
    ]
    if failures:
        joined = ", ".join(failures)
        raise SystemExit(f"warm cache proof failed: {joined} reported zero cached tokens")

def load_workloads(corpus: Path | None) -> list[Workload]:
    workloads = [Workload(name, prompt) for name, prompt in BUILT_IN_WORKLOADS.items()]
    corpus = corpus or HERE / "skippy-coding-agent-loop.jsonl"
    if not corpus.exists():
        return workloads
    with corpus.open(encoding="utf-8") as handle:
        for line_number, raw in enumerate(handle, start=1):
            if not raw.strip():
                continue
            row = json.loads(raw)
            prompt = row.get("prompt")
            if not isinstance(prompt, str) or not prompt:
                raise ValueError(f"{corpus}:{line_number} has no non-empty prompt")
            name = str(row.get("id") or f"corpus-{line_number}")
            workloads.append(Workload(name, prompt))
    return workloads

def response_text(response: dict[str, Any]) -> tuple[str, str]:
    choices = response.get("choices") or []
    if not choices:
        raise ValueError("chat response contains no choices")
    choice = choices[0]
    content = (choice.get("message") or {}).get("content") or ""
    return str(content), str(choice.get("finish_reason") or "unknown")

def summarize(samples: list[Sample], baseline_arm: str) -> dict[str, Any]:
    grouped: dict[tuple[str, str], list[Sample]] = {}
    for sample in samples:
        grouped.setdefault((sample.arm, sample.workload), []).append(sample)

    rows: list[dict[str, Any]] = []
    for (arm, workload), group in sorted(grouped.items()):
        hybrid_tokens = sum(sample.ngram_tokens for sample in group)
        standalone_tokens = sum(sample.draft_n for sample in group)
        proposal_tokens = hybrid_tokens or standalone_tokens
        accepted = (
            sum(sample.ngram_accepted_tokens for sample in group)
            if hybrid_tokens
            else sum(sample.draft_accepted for sample in group)
        )
        rows.append(
            {
                "arm": arm,
                "workload": workload,
                "samples": len(group),
                "wall_tok_s_median": median(group, "wall_tok_s"),
                "server_tok_s_median": median(group, "server_tok_s"),
                "server_tok_s_stdev": statistics.stdev(
                    sample.server_tok_s for sample in group
                )
                if len(group) > 1
                else 0.0,
                "proposal_mode": "mtp-hybrid" if hybrid_tokens else "standalone",
                "ngram_tokens": proposal_tokens,
                "ngram_accepted_tokens": accepted,
                "ngram_acceptance": accepted / proposal_tokens if proposal_tokens else 0.0,
                "proposer_match_length_max": max(
                    sample.proposer_match_length_max for sample in group
                ),
                "proposer_candidates_examined": sum(
                    sample.proposer_candidates_examined for sample in group
                ),
                "proposer_lookup_us": sum(sample.proposer_lookup_us for sample in group),
            }
        )

    mismatches: list[dict[str, Any]] = []
    by_identity = {(sample.arm, sample.workload, sample.run): sample for sample in samples}
    for sample in samples:
        baseline = by_identity.get((baseline_arm, sample.workload, sample.run))
        if baseline and baseline.output_sha256 != sample.output_sha256:
            mismatches.append(
                {
                    "arm": sample.arm,
                    "workload": sample.workload,
                    "run": sample.run,
                    "baseline_sha256": baseline.output_sha256,
                    "output_sha256": sample.output_sha256,
                }
            )
    return {"rows": rows, "output_hash_mismatches": mismatches}

def default_output_dir() -> Path:
    stamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ")
    return Path("target/skippy-suffix-proposer-bench") / stamp

def parse_arms(values: list[str]) -> dict[str, str]:
    arms: dict[str, str] = {}
    for value in values:
        if "=" not in value:
            raise ValueError(f"invalid arm {value!r}; expected NAME=URL")
        name, url = value.split("=", 1)
        if not name or not url or name in arms:
            raise ValueError(f"invalid or duplicate arm {value!r}")
        arms[name] = url
    return arms

def expected_server_mode(guardrail_mode: str) -> str:
    return {
        "off": "disabled",
        "metrics": "metrics",
        "enforce": "enforce",
    }[guardrail_mode]

def base_request(case: CorpusCase, *, model: str, guardrail_mode: str) -> dict[str, Any]:
    request = {
        "model": model,
        "messages": [{"role": "user", "content": case.prompt}],
        "temperature": 0,
        "mesh_guardrails": guardrail_mode != "off",
    }
    request.update(case.request_overrides)
    return request

def runtime_available(base_url: str) -> bool:
    if base_url.startswith("fake://"):
        return False
    request = urllib.request.Request(
        f"{base_url.rstrip('/')}/models",
        headers={"Authorization": f"Bearer {API_KEY}"},
    )
    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            payload = json.load(response)
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError):
        return False
    return bool(payload.get("data"))

def read_stream_text(response: Any) -> str:
    parts: list[str] = []
    while True:
        line = response.readline()
        if not line:
            break
        text = line.decode("utf-8", errors="replace").strip()
        if not text or not text.startswith("data:"):
            continue
        data = text.removeprefix("data:").strip()
        if data == "[DONE]":
            break
        payload = json.loads(data)
        for choice in payload.get("choices", []):
            delta = choice.get("delta") or {}
            content = delta.get("content")
            if isinstance(content, str) and content:
                parts.append(content)
    return "".join(parts).strip()

def live_case_result(base_url: str, case: CorpusCase, request_body: dict[str, Any]) -> dict[str, Any]:
    payload = json.dumps(request_body).encode("utf-8")
    url = f"{base_url.rstrip('/')}/chat/completions"
    req = urllib.request.Request(
        url,
        data=payload,
        method="POST",
        headers={
            "Authorization": f"Bearer {API_KEY}",
            "Content-Type": "application/json",
        },
    )
    started = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT_SECS) as response:
            if request_body.get("stream"):
                text = read_stream_text(response)
                elapsed = (time.perf_counter() - started) * 1000.0
                return {
                    "ok": bool(text),
                    "status": 200,
                    "response_kind": "stream",
                    "latency_ms": elapsed,
                }
            body = json.load(response)
    except urllib.error.HTTPError as exc:
        elapsed = (time.perf_counter() - started) * 1000.0
        detail = exc.read().decode("utf-8", errors="replace")
        return {
            "ok": False,
            "status": exc.code,
            "response_kind": "error",
            "error": detail,
            "latency_ms": elapsed,
        }
    except urllib.error.URLError as exc:
        raise RuntimeError(f"runtime unavailable: {exc}") from exc

    elapsed = (time.perf_counter() - started) * 1000.0
    choices = body.get("choices") or []
    first_choice = choices[0] if choices else {}
    message = first_choice.get("message") or {}
    content = message.get("content")
    tool_calls = message.get("tool_calls") or []
    ok = case.expected_outcome != "unsupported_real_tools_plus_strict_structured"
    if case.expected_outcome == "unsupported_real_tools_plus_strict_structured":
        ok = False
    elif body.get("error"):
        ok = False
    elif not content and not tool_calls and not body.get("output_text"):
        ok = False
    return {
        "ok": ok,
        "status": 200,
        "response_kind": "chat",
        "latency_ms": elapsed,
    }

